import{_ as a,o as t,c as r,a2 as i}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Learning Spells","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/magic/learning-spells.md","filePath":"en/guide/magic/learning-spells.md"}'),l={name:"en/guide/magic/learning-spells.md"};function n(s,e,o,d,c,h){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="learning-spells" tabindex="-1">Learning Spells <a class="header-anchor" href="#learning-spells" aria-label="Permalink to &quot;Learning Spells&quot;">​</a></h1><p><strong>Status:</strong> Proposed · Availability not established.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>A <a href="/Syrolands-Public/en/guide/glossary.html#core-pattern">Core Pattern</a> is learned knowledge, separate from Magery.</li><li>Teachers, books and exploration can reveal new magical possibilities.</li><li>An ordinary casting scroll does not permanently teach its spell.</li></ul><p><span id="at-a-glance"></span></p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Element</th><th>Player meaning</th></tr></thead><tbody><tr><td>Discover</td><td>Seek teachers, academies, manuscripts, ruins and other sources of knowledge.</td></tr><tr><td>Learn</td><td>Acquire a pattern independently of reaching a <a href="/Syrolands-Public/en/guide/characters/skills.html">skill</a> threshold. Exact teaching gates remain open.</td></tr><tr><td>Execute</td><td>Magery supports reliability; knowing a difficult pattern does not guarantee a successful cast.</td></tr><tr><td>Practice and prepare</td><td>Build <a href="/Syrolands-Public/en/guide/characters/familiarity.html">Familiarity</a> (practical fluency) and choose patterns for <a href="/Syrolands-Public/en/guide/magic/memory-and-familiarity.html">Active Memory</a>.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Compared with classic UO <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Permalink to &quot;Compared with classic UO&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Classic UO</th><th>Syrolands direction</th></tr></thead><tbody><tr><td>Magery scrolls can fill a spellbook.</td><td>Permanent learning follows knowledge sources and teaching rules; ordinary casting scrolls give temporary access.</td></tr><tr><td>Skill influences whether a cast succeeds.</td><td>Retain execution skill while making discovery and per-pattern practice separate achievements.</td></tr></tbody></table><p>UO rules vary by era and shard. <a href="https://uo.com/wiki/ultima-online-wiki/skills/an-introduction-to-spellcasting/" target="_blank" rel="noreferrer">Official UO: spellcasting</a>.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>A mage may discover Remove Curse in a manuscript yet still need training to cast it reliably and preparation to avoid consulting that reference during danger. The spell is an illustrative example.</p><h2 id="progression-trade-offs" tabindex="-1">Progression / trade-offs <a class="header-anchor" href="#progression-trade-offs" aria-label="Permalink to &quot;Progression / trade-offs&quot;">​</a></h2><p>Schools and wider <a href="/Syrolands-Public/en/guide/glossary.html#mastery">Mastery</a> (specialist understanding) remain distinct from individual patterns. Player teaching and special learning artifacts need rules; buying a casting scroll is not an automatic shortcut to permanent knowledge.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/magic/memory-and-familiarity.html">Memory and Familiarity</a> · <a href="/Syrolands-Public/en/guide/magic/spellbooks-scrolls-and-reagents.html">Scrolls and books</a> · <a href="/Syrolands-Public/en/guide/characters/skills.html">Skills and teachers</a></p><h2 id="full-design-specification" tabindex="-1">Full design specification <a class="header-anchor" href="#full-design-specification" aria-label="Permalink to &quot;Full design specification&quot;">​</a></h2><p>Read the <a href="/Syrolands-Public/en/game-design/magic/spell-knowledge.html">Learning Spells</a> design specification.</p>',18)])])}const g=a(l,[["render",n]]);export{u as __pageData,g as default};
